52	    final path =
53	        '${dir.path}/cerne_audio_entry_'
54	        '${DateTime.now().microsecondsSinceEpoch}.wav';
55	    await _recorder.start(
56	      // 16kHz mono matches `whisper_ggml`'s own expected input exactly
57	      // (its internal ffmpeg conversion step — `WhisperAudioConvert` —
58	      // falls back to passing the file through unconverted when ffmpeg
59	      // is unavailable, which only works if it's already in this shape).
60	      const record_pkg.RecordConfig(
61	        encoder: record_pkg.AudioEncoder.wav,
62	        sampleRate: 16000,
63	        numChannels: 1,
64	      ),
65	      path: path,
66	    );
67	    _startedAt = _now();
68	    _currentPath = path;
69	  }
70	
71	  @override
72	  Future<MicRecording?> stop() async {
73	    final path = await _recorder.stop();
74	    final startedAt = _startedAt;
75	    _startedAt = null;
76	    _currentPath = null;
77	    if (path == null || startedAt == null) {
78	      return null;
79	    }
80	    // Review finding: a backward system-clock adjustment mid-recording
81	    // (DST/NTP correction) could otherwise make this negative, which the
82	    // backend's `mediaDurationSeconds: minimum 0` contract rejects —
83	    // floored at 0 rather than trusting the wall clock never moves back.
84	    final elapsed = _now().difference(startedAt).inSeconds;
85	    return MicRecording(
86	      path: path,
87	      durationSeconds: elapsed < 0 ? 0 : elapsed,
88	    );
89	  }
90	
91	  @override
92	  Future<void> cancel() async {
93	    _startedAt = null;
94	    final path = _currentPath;
95	    _currentPath = null;
96	    await _recorder.cancel();
97	    // Review finding: don't rely solely on the plugin's own "cancel
98	    // deletes the file" contract — delete it ourselves too, best-effort,
99	    // so this class's own doc comment stays true regardless of the
100	    // underlying plugin's actual behavior.
101	    if (path != null) {
102	      try {
103	        await File(path).delete();
104	      } catch (_) {
105	        // Best-effort — the plugin may have already deleted it itself,
106	        // or it may never have existed (e.g. a very early cancel).
107	      }
108	    }
109	  }
110	
111	  @override
112	  Stream<double> get amplitudeStream => _recorder
113	      .onAmplitudeChanged(const Duration(milliseconds: 200))
114	      .map(_normalize);
115	
116	  /// `record`'s own `Amplitude.current` is dBFS, roughly -45 (near
117	  /// silence, in practice — the package's own floor is -160 but normal
118	  /// mic noise never gets that quiet) to 0 (loudest) — rescaled to a
119	  /// 0.0–1.0 range the waveform widget can use directly, with no
120	  /// `package:record` type ever crossing the [MicRecorder] boundary.
121	  double _normalize(record_pkg.Amplitude amplitude) {
122	    const floorDb = -45.0;
123	    final clamped = amplitude.current.clamp(floorDb, 0.0);
124	    return (clamped - floorDb) / -floorDb;
125	  }
126	}
