110	/// Drives the Áudio tab's recording -> processing -> transcribed/error
111	/// pipeline (Intent). A fresh, `get_it`-factory-scoped instance per "+"
112	/// tap, same convention as `TextEntryCubit` — [MicRecorder]/
113	/// [AudioTranscriber] themselves stay long-lived `get_it` singletons
114	/// (`capture_injection.dart`), shared across every modal open the way
115	/// `EntriesRepository` already is for `TextEntryCubit`.
116	class AudioEntryCubit extends Cubit<AudioCaptureState> {
117	  AudioEntryCubit(this._micRecorder, this._audioTranscriber, this._repository)
118	    : super(const AudioIdle());
119	
120	  final MicRecorder _micRecorder;
121	  final AudioTranscriber _audioTranscriber;
122	  final EntriesRepository _repository;
123	
124	  Timer? _elapsedTimer;
125	
126	  /// Bumped by [cancel] so an in-flight [startRecording]/[stopRecording]
127	  /// continuation can tell "the user already left the Áudio tab while I
128	  /// was awaiting" apart from "nothing has changed since I started" —
129	  /// the same role `isClosed` already plays for `close()`, but for a tab
130	  /// switch that doesn't close the cubit itself (Review finding: without
131	  /// this, `cancel()` running mid-await either left the recorder running
132	  /// unobserved, or let a stale `stop()`/transcription result resurrect a
133	  /// flow the user already left).
134	  int _generation = 0;
135	
136	  /// Guards [stopRecording] against a second concurrent call (e.g. a fast
137	  /// double-tap on the stop control before the UI rebuilds past
138	  /// [AudioRecording]) — without this, a second `_micRecorder.stop()` call
139	  /// racing the first could return `null` (nothing left to stop) and
140	  /// overwrite a perfectly good [AudioProcessing]/transcription result
141	  /// with a bogus [AudioError] (Review finding).
142	  bool _stopping = false;
143	
144	  /// Forwarded straight from [MicRecorder.amplitudeStream] — lets
145	  /// `_AudioTab`'s waveform animate without ever importing `package:record`
146	  /// itself (Boundaries).
147	  Stream<double> get amplitudeStream => _micRecorder.amplitudeStream;
