236	  void _startElapsedTimer() {
237	    _elapsedTimer?.cancel();
238	    var elapsed = 0;
239	    _elapsedTimer = Timer.periodic(const Duration(seconds: 1), (_) {
240	      elapsed++;
241	      if (state is AudioRecording) {
242	        emit(AudioRecording(elapsedSeconds: elapsed));
243	      }
244	    });
245	  }
