247	  /// Stops recording and immediately kicks off transcription — the I/O
248	  /// matrix's "Happy path"/"Transcription fails" rows. Ignored outside
249	  /// [AudioRecording] (e.g. a stray second tap on the stop control) and
250	  /// — Review finding — ignored while a previous call is still awaiting
251	  /// `_micRecorder.stop()` ([_stopping]): without this, a fast double-tap
252	  /// on the stop control could fire a second `_micRecorder.stop()` call
253	  /// that returns `null` (nothing left to stop) and clobber the first
254	  /// call's genuine result with a bogus `AudioError`.
255	  Future<void> stopRecording() async {
256	    if (state is! AudioRecording || _stopping) {
257	      return;
258	    }
259	    _stopping = true;
260	    final generation = _generation;
261	    _elapsedTimer?.cancel();
262	    MicRecording? recording;
263	    try {
264	      recording = await _micRecorder.stop();
265	    } catch (_) {
266	      // Review finding: a thrown `PlatformException` must never escape
267	      // uncaught — surfaces through the normal error/retry path instead.
268	      // Also releases the native recorder best-effort (Review finding):
269	      // a failed `stop()` leaves the actual native session state
270	      // unconfirmed, so this is the only chance to try to release it.
271	      _stopping = false;
272	      unawaited(_safeCancelRecorder());
273	      if (isClosed || generation != _generation) {
274	        return;
275	      }
276	      emit(
277	        const AudioError(
278	          path: null,
279	          durationSeconds: null,
280	          message: 'Não foi possível gravar o áudio.',
281	        ),
282	      );
283	      return;
284	    }
285	    _stopping = false;
286	    // Review finding: without the `_generation` check, a `cancel()` that
287	    // ran while `_micRecorder.stop()` was in flight (tab switch right
288	    // after tapping stop) already reset the cubit to `AudioIdle` — this
289	    // continuation must not resurrect the flow with a stale
290	    // `AudioProcessing`/`AudioError` emission on top of that reset.
291	    if (isClosed || generation != _generation) {
292	      return;
293	    }
294	    if (recording == null) {
295	      // Stopped with nothing actually captured — the I/O matrix has no
296	      // dedicated row for this (it should be unreachable in practice: the
297	      // recorder was just started above), but `AudioError` with no file
298	      // still gives the user a path back in via retry's permission-
299	      // re-request branch rather than leaving the cubit stuck mid-flow.
300	      emit(
301	        const AudioError(
302	          path: null,
303	          durationSeconds: null,
304	          message: 'Não foi possível gravar o áudio.',
305	        ),
306	      );
307	      return;
308	    }
309	    emit(
310	      AudioProcessing(
311	        path: recording.path,
312	        durationSeconds: recording.durationSeconds,
313	      ),
314	    );
315	    await _transcribe(recording.path, recording.durationSeconds);
316	  }
317	
318	  Future<void> _transcribe(String path, int durationSeconds) async {
319	    final text = await _audioTranscriber.transcribe(path);
320	    if (isClosed) {
321	      return;
322	    }
323	    // Guards a tab switch away mid-processing (`cancel()`, below) that
324	    // already reset the state to `AudioIdle` by the time this resolves —
325	    // without this, the eventual transcription result would still land
326	    // and resurrect a flow the user already left.
327	    if (state is! AudioProcessing ||
328	        (state as AudioProcessing).path != path) {
329	      return;
330	    }
331	    if (text == null) {
332	      emit(
333	        AudioError(
334	          path: path,
335	          durationSeconds: durationSeconds,
336	          message: 'Não foi possível transcrever o áudio.',
337	        ),
338	      );
339	      return;
340	    }
341	    emit(
342	      AudioTranscribed(
343	        path: path,
344	        durationSeconds: durationSeconds,
345	        text: text,
346	        saving: false,
347	      ),
348	    );
349	  }
