351	  /// "Tentar novamente" — re-requests permission when no file was ever
352	  /// recorded, or re-transcribes the same preserved file otherwise (I/O
353	  /// matrix: never re-records, never auto-retries on its own). A no-op
354	  /// outside [AudioError], or for a save failure (non-null [AudioError.
355	  /// text]) — that case's own retry is just tapping Salvar again, handled
356	  /// by [save] directly, not this method.
357	  Future<void> retry() async {
358	    final current = state;
359	    if (current is! AudioError || current.text != null) {
360	      return;
361	    }
362	    final path = current.path;
363	    final durationSeconds = current.durationSeconds;
364	    if (path == null || durationSeconds == null) {
365	      await startRecording();
366	      return;
367	    }
368	    emit(AudioProcessing(path: path, durationSeconds: durationSeconds));
369	    await _transcribe(path, durationSeconds);
370	  }
371	
372	  /// Mirrors the Texto field's own `updateText` — keeps the transcribed
373	  /// text editable before Salvar (Acceptance Criteria). Ignored while a
374	  /// save is already in flight, same rationale as `TextEntryCubit.
375	  /// updateText`.
376	  void updateText(String text) {
377	    final current = state;
378	    if (current is AudioTranscribed && !current.saving) {
379	      emit(current.copyWith(text: text));
380	    } else if (current is AudioError && current.text != null) {
381	      // Review finding: a save failure (`AudioError` with non-null
382	      // `text`) renders the same editable field as `AudioTranscribed`
383	      // (`_AudioErrorView`'s non-retry branch) — without this branch,
384	      // typing there updated the `TextField`'s own controller visually
385	      // but never the cubit's record of the text, so a retried `save()`
386	      // would silently resend the stale pre-failure text.
387	      emit(
388	        AudioError(
389	          path: current.path,
390	          durationSeconds: current.durationSeconds,
391	          message: current.message,
392	          text: text,
393	        ),
394	      );
395	    }
396	  }
397	
398	  /// Called when the Áudio tab loses focus mid-recording/mid-processing
399	  /// (`InsertionModal`'s tab-switch listener) — the I/O matrix's "Leave
400	  /// tab mid-recording" row: stops/releases the recorder, no `create()`
401	  /// ever fires. A no-op for every other state when [discardPreserved] is
402	  /// `false` (the default) — in particular [AudioTranscribed]/[AudioError],
403	  /// where the Never clause's trivial scope (resource safety only, not
404	  /// full Story 3.4 cancel-safety) means a tab switch must preserve the
405	  /// result rather than discard it.
406	  ///
407	  /// [discardPreserved] — Review finding: `InsertionModal.show()`'s
408	  /// `finally` also calls this (before `close()`) when the *whole modal*
409	  /// is dismissed (✕/swipe-down/barrier tap), not just the tab. In that
410	  /// case there's no "switch back to the tab later" to preserve for —
411	  /// the cubit is about to be closed — so a preserved [AudioTranscribed]
412	  /// or file-carrying [AudioError]'s temp file would otherwise never be
413	  /// cleaned up and leak on disk forever. Pass `true` only from that
414	  /// call site.
415	  Future<void> cancel({bool discardPreserved = false}) async {
416	    // Bumped unconditionally — including when the state below doesn't
417	    // match either branch — so an in-flight `startRecording()`/
418	    // `stopRecording()` continuation still sees the mismatch and aborts
419	    // itself (Review finding: previously only invalidated a flow already
420	    // visible in `state`, missing the window while those methods were
421	    // still awaiting).
422	    _generation++;
423	    // Review finding: without this, a hung `_micRecorder.stop()` call
424	    // (one that never resolves) left `_stopping` stuck `true` forever —
425	    // `stopRecording()`'s own guard made it a permanent no-op for the
426	    // rest of this cubit's life. The `_generation` bump above already
427	    // makes that stale continuation's eventual result a no-op, so
428	    // resetting this eagerly is always safe, mirroring `PhotoEntryCubit.
429	    // cancel()`'s own `_picking = false` reset.
430	    _stopping = false;
431	    final current = state;
432	    if (current is AudioRecording) {
433	      _elapsedTimer?.cancel();
434	      await _safeCancelRecorder();
435	      if (isClosed) {
436	        return;
437	      }
438	      emit(const AudioIdle());
439	    } else if (current is AudioProcessing) {
440	      // The recorder itself is already stopped by the time this state is
441	      // reached (`stopRecording` stops it before emitting `AudioProcessing`)
442	      // — only resetting the cubit's own state is left, so the pending
443	      // `_transcribe` continuation's own `state is! AudioProcessing` guard
444	      // (above) drops its result instead of resurrecting this flow. Review
445	      // finding: the already-recorded file is abandoned for good at this
446	      // point (nothing will ever retry it), so it must be deleted here —
447	      // the other orphan-file case `_micRecorder.cancel()` above already
448	      // handles on its own.
449	      unawaited(_deleteRecordingFile(current.path));
450	      emit(const AudioIdle());
451	    } else if (discardPreserved) {
452	      final path = switch (current) {
453	        AudioTranscribed(path: final p) => p,
454	        AudioError(path: final p) => p,
455	        _ => null,
456	      };
457	      if (path != null) {
458	        unawaited(_deleteRecordingFile(path));
459	      }
460	    }
461	  }
462	
463	  /// Best-effort `_micRecorder.cancel()` — a thrown `PlatformException`
464	  /// here (Review finding) must never escape uncaught, since both call
465	  /// sites (above, and [startRecording]'s own abandon-on-generation-
466	  /// mismatch branch) call this fire-and-forget.
467	  Future<void> _safeCancelRecorder() async {
468	    try {
469	      await _micRecorder.cancel();
470	    } catch (_) {
471	      // Best-effort — nothing in the UI depends on this succeeding.
472	    }
473	  }
474	
475	  /// I/O matrix's "Happy path"/"Save fails" rows: fires `POST /entries`
476	  /// with `source: audio` and `mediaDurationSeconds` for the current
477	  /// transcribed text. Mirrors `TextEntryCubit.save()`'s `isClosed`/
478	  /// no-double-submit guards exactly (Boundaries).
479	  ///
480	  /// Review finding: also callable from an [AudioError] save failure
481	  /// (non-null [AudioError.text]) — `_AudioErrorView`'s non-retry branch
482	  /// re-renders the editable field and calls this same method for its
483	  /// "Salvar" button, but the original guard only matched
484	  /// [AudioTranscribed], making a retry after any save failure a
485	  /// permanent no-op.
486	  Future<void> save() async {
487	    final current = state;
488	    final String path;
489	    final int durationSeconds;
490	    final String text;
491	    if (current is AudioTranscribed && !current.saving) {
492	      path = current.path;
493	      durationSeconds = current.durationSeconds;
494	      text = current.text.trim();
495	    } else if (current is AudioError &&
496	        current.text != null &&
497	        current.path != null &&
498	        current.durationSeconds != null) {
499	      path = current.path!;
500	      durationSeconds = current.durationSeconds!;
501	      text = current.text!.trim();
502	    } else {
503	      return;
504	    }
505	    if (text.isEmpty) {
506	      return;
507	    }
508	    emit(
509	      AudioTranscribed(
510	        path: path,
511	        durationSeconds: durationSeconds,
512	        text: text,
513	        saving: true,
514	      ),
515	    );
516	    final result = await _repository.create(
517	      content: text,
518	      source: EntrySource.audio,
519	      mediaDurationSeconds: durationSeconds,
520	    );
521	    // Mirrors `TextEntryCubit.save()`'s own `isClosed` guard — this
522	    // cubit's `close()` can race the awaited call above (e.g. the modal's
523	    // barrier is dismissed mid-save).
524	    if (isClosed) {
525	      return;
526	    }
527	    result.match(
528	      (failure) => emit(
529	        AudioError(
530	          path: path,
531	          durationSeconds: durationSeconds,
532	          message: failure.message,
533	          text: text,
534	        ),
535	      ),
536	      (_) {
537	        // Review finding: the recorded temp file was never deleted after
538	        // a successful save — fire-and-forget, a deletion failure must
539	        // never block the modal from closing.
540	        unawaited(_deleteRecordingFile(path));
541	        emit(const AudioSaved());
542	      },
543	    );
544	  }
545	
546	  /// Best-effort cleanup for a temp recording file this cubit is done
547	  /// with (saved successfully, or abandoned for good by [cancel] mid-
548	  /// processing) — deletion failures are swallowed since nothing in the
549	  /// UI depends on this succeeding (Review finding: previously never
550	  /// called at all, leaking a `.wav` file per recording indefinitely).
551	  Future<void> _deleteRecordingFile(String path) async {
552	    try {
553	      await File(path).delete();
554	    } catch (_) {
555	      // Best-effort — a missing/already-deleted file, or a transient
556	      // disk error, is never worth surfacing to the user.
557	    }
558	  }
559	
560	  @override
561	  Future<void> close() {
562	    _elapsedTimer?.cancel();
563	    return super.close();
564	  }
565	}
