13	/// `PhotoEntryCubit`'s own sealed state hierarchy — separate from
14	/// `TextEntryState`/`AudioCaptureState` (Boundaries: "own sealed
15	/// `PhotoCaptureState`"). No common base-class field, same rationale as
16	/// `AudioCaptureState`: [PhotoIdle] has nothing in common with
17	/// [PhotoRecognized], for instance.
18	sealed class PhotoCaptureState {
19	  const PhotoCaptureState();
20	}
21	
22	/// The state immediately after the modal opens on the Foto tab, after
23	/// leaving mid-pick/mid-OCR (Never: this story's trivial cross-tab
24	/// case), and the state a fresh `PhotoEntryCubit` always starts in.
25	/// `InsertionModal`'s own `_FotoTab` renders the Câmera/Galeria capture
26	/// buttons for this state.
27	class PhotoIdle extends PhotoCaptureState {
28	  const PhotoIdle();
29	}
30	
31	/// A photo was picked, `MediaRepository.recognizeText()` in flight —
32	/// `_FotoTab` shows a thumbnail + "Reconhecendo texto..." for the whole
33	/// duration of this state (Acceptance Criteria). No separate "recording"-
34	/// style intermediate phase (Design Notes): picking is one blocking OS
35	/// call, so [PhotoIdle] goes straight here once the picker returns a file.
36	class PhotoProcessing extends PhotoCaptureState {
37	  const PhotoProcessing({required this.path, required this.mimeType});
38	
39	  final String path;
40	  final String mimeType;
41	}
42	
43	/// OCR succeeded with usable text — [text] is editable before Salvar
44	/// (Acceptance Criteria), mirrored by [PhotoEntryCubit.updateText].
45	/// [saving] folds `TextEntrySaving`'s role into this same state, same
46	/// convention as `AudioTranscribed.saving`.
47	class PhotoRecognized extends PhotoCaptureState {
48	  const PhotoRecognized({
49	    required this.path,
50	    required this.mimeType,
51	    required this.text,
52	    required this.saving,
53	  });
54	
55	  final String path;
56	  final String mimeType;
57	  final String text;
58	  final bool saving;
59	
60	  PhotoRecognized copyWith({String? text, bool? saving}) => PhotoRecognized(
61	    path: path,
62	    mimeType: mimeType,
63	    text: text ?? this.text,
64	    saving: saving ?? this.saving,
65	  );
66	}
67	
68	/// A save attempt succeeded — `InsertionModal`'s listener reacts to this
69	/// exactly like `TextEntrySaved`/`AudioSaved` (announce, then pop).
70	/// Terminal, same rationale as those two states' own docs.
71	class PhotoSaved extends PhotoCaptureState {
72	  const PhotoSaved();
73	}
74	
75	/// The 3-way discriminator driving `_FotoTab`'s three distinct error
76	/// branches (Design Notes: "a discriminator is clearer than overloading
77	/// nullability tricks" — unlike `AudioError`'s binary `canRetry`, Photo
78	/// has two distinct non-retryable backend codes needing different UI).
79	enum PhotoErrorKind {
80	  /// `Failure.ocrNoText` — "Tentar novamente" (re-OCRs the same image)
81	  /// and "Salvar só a foto" (saves a fixed placeholder) are both offered.
82	  ocrNoText,
83	
84	  /// `Failure.payloadTooLarge` — no retry, no save-without-text; the only
85	  /// way forward is picking a different photo.
86	  payloadTooLarge,
87	
88	  /// Any other `Failure` — a generic OCR-call failure ([text] `null`,
89	  /// "Tentar novamente" re-OCRs) or a save failure ([text] non-null,
90	  /// re-running the failed call means tapping Salvar again, same shape
91	  /// as `AudioError`).
92	  generic,
93	}
94	
95	/// The last attempt failed — covers every failure row of the I/O matrix:
96	/// `OCR_NO_TEXT`, `PAYLOAD_TOO_LARGE`, a generic OCR-call failure, or a
97	/// save failure (non-null [text]).
98	class PhotoError extends PhotoCaptureState {
99	  const PhotoError({
100	    required this.path,
101	    required this.mimeType,
102	    required this.message,
103	    required this.kind,
104	    this.text,
105	  });
106	
107	  final String path;
108	  final String mimeType;
109	  final String message;
110	  final PhotoErrorKind kind;
111	
112	  /// Non-null only for a save failure ([PhotoErrorKind.generic]) — lets
113	  /// `_FotoTab` keep rendering the editable text field under the inline
114	  /// error, same as `AudioError.text`/`TextEntryError`'s own rendering.
115	  final String? text;
116	}
117	
118	/// Drives the Foto tab's pick -> processingOcr -> recognized/error
119	/// pipeline (Intent). A fresh, `get_it`-factory-scoped instance per "+"
120	/// tap, same convention as `TextEntryCubit`/`AudioEntryCubit` —
121	/// [PhotoPicker]/[MediaRepository] themselves stay long-lived `get_it`
122	/// singletons (`capture_injection.dart`).
123	class PhotoEntryCubit extends Cubit<PhotoCaptureState> {
124	  PhotoEntryCubit(
125	    this._photoPicker,
126	    this._mediaRepository,
127	    this._entriesRepository,
128	  ) : super(const PhotoIdle());
129	
130	  final PhotoPicker _photoPicker;
131	  final MediaRepository _mediaRepository;
132	  final EntriesRepository _entriesRepository;
133	
134	  static const _noTextPlaceholder =
135	      'Registro fotográfico (sem texto reconhecido)';
136	
137	  /// Bumped by [cancel] (and by every pick/retry attempt) so an in-flight
138	  /// picker/OCR continuation can tell "the user already left the Foto tab"
139	  /// apart from "nothing has changed since I started" — same role
140	  /// `AudioEntryCubit._generation` plays for the picker call and the OCR
141	  /// network call here (Boundaries).
142	  int _generation = 0;
143	
144	  /// Guards against a second overlapping picker call (e.g. a fast
145	  /// double-tap on Câmera before the UI rebuilds past [PhotoIdle]).
146	  bool _picking = false;
147	
148	  Future<void> pickFromCamera() => _pick(_photoPicker.pickFromCamera);
149	
150	  Future<void> pickFromGallery() => _pick(_photoPicker.pickFromGallery);
151	
152	  Future<void> _pick(Future<PickedPhoto?> Function() pick) async {
153	    final current = state;
154	    final canPick =
155	        !_picking &&
156	        (current is PhotoIdle ||
157	            (current is PhotoError &&
158	                current.kind == PhotoErrorKind.payloadTooLarge));
159	    if (!canPick) {
160	      return;
161	    }
162	    // A fresh pick replacing a previous `payloadTooLarge` error's own
163	    // (never-OCR'd, now-abandoned) file — Review finding: without this,
164	    // that file leaked on disk forever once this new pick's own file
165	    // takes over `state`. Deleted unconditionally right away (Review
166	    // finding): this old file is abandoned the moment a new pick starts,
167	    // regardless of whether that new pick succeeds, is canceled, or
168	    // throws — the earlier code only deleted it on success, leaking it
169	    // on every other exit path.
170	    final previousPath = current is PhotoError ? current.path : null;
171	    if (previousPath != null) {
172	      unawaited(_deletePickedFile(previousPath));
173	    }
174	    _picking = true;
175	    final generation = ++_generation;
176	    PickedPhoto? photo;
177	    try {
178	      photo = await pick();
179	    } catch (_) {
180	      // A thrown PlatformException (native-side error) must never escape
181	      // uncaught — treated the same as a plain user cancel, since this
182	      // story offers no dedicated "picker failed" UI (not in the I/O
183	      // matrix).
184	      _picking = false;
185	      if (isClosed || generation != _generation) {
186	        return;
187	      }
188	      emit(const PhotoIdle());
189	      return;
190	    }
191	    _picking = false;
192	    if (isClosed || generation != _generation) {
193	      // Review finding: without this, a photo picked just as the user
194	      // left the tab (or closed the whole modal) was discarded with no
195	      // cleanup — its OS temp file leaked forever.
196	      if (photo != null) {
197	        unawaited(_deletePickedFile(photo.path));
198	      }
199	      return;
200	    }
201	    if (photo == null) {
202	      // I/O matrix: "User cancels picker" -> stays on PhotoIdle's capture
203	      // buttons. If the re-pick was attempted from a `payloadTooLarge`
204	      // error, drop that stale error too rather than leaving it on
205	      // screen with nothing that produced it anymore.
206	      if (current is PhotoError) {
207	        emit(const PhotoIdle());
208	      }
209	      return;
210	    }
211	    emit(PhotoProcessing(path: photo.path, mimeType: photo.mimeType));
212	    await _recognize(photo.path, photo.mimeType, generation);
213	  }
214	
215	  Future<void> _recognize(String path, String mimeType, int generation) async {
216	    Uint8List bytes;
217	    try {
218	      bytes = await File(path).readAsBytes();
219	    } catch (_) {
220	      if (isClosed || generation != _generation) {
221	        return;
222	      }
223	      emit(
224	        PhotoError(
225	          path: path,
226	          mimeType: mimeType,
227	          message: 'Não foi possível ler a foto selecionada.',
228	          kind: PhotoErrorKind.generic,
229	        ),
230	      );
231	      return;
232	    }
233	    final result = await _mediaRepository.recognizeText(
234	      imageBytes: bytes,
235	      mimeType: mimeType,
236	    );
237	    // Guards a tab switch away mid-OCR (`cancel()`, below) that already
238	    // reset the state by the time this resolves — without this, a stale
239	    // OCR result would still land and resurrect a flow the user left.
240	    if (isClosed || generation != _generation) {
241	      return;
242	    }
243	    result.match(
244	      (failure) => emit(
245	        PhotoError(
246	          path: path,
247	          mimeType: mimeType,
248	          message: failure.message,
249	          kind: switch (failure) {
250	            OcrNoText() => PhotoErrorKind.ocrNoText,
251	            PayloadTooLarge() => PhotoErrorKind.payloadTooLarge,
252	            _ => PhotoErrorKind.generic,
253	          },
254	        ),
255	      ),
256	      (ocr) => emit(
257	        PhotoRecognized(
258	          path: path,
259	          mimeType: mimeType,
260	          text: ocr.text,
261	          saving: false,
262	        ),
263	      ),
264	    );
265	  }
266	
267	  /// "Tentar novamente" — re-OCRs the same image for an [OcrNoText]
268	  /// error or a generic OCR-call failure ([PhotoError.text] `null`). A
269	  /// no-op for [PhotoErrorKind.payloadTooLarge] (I/O matrix: no retry
270	  /// offered) and for a generic *save* failure (non-null [PhotoError.
271	  /// text]) — that case's own retry is tapping Salvar again, handled by
272	  /// [save] directly, mirroring `AudioEntryCubit.retry()`.
273	  Future<void> retry() async {
274	    final current = state;
275	    if (current is! PhotoError ||
276	        current.text != null ||
277	        current.kind == PhotoErrorKind.payloadTooLarge) {
278	      return;
279	    }
280	    final generation = ++_generation;
281	    emit(PhotoProcessing(path: current.path, mimeType: current.mimeType));
282	    await _recognize(current.path, current.mimeType, generation);
283	  }
284	
285	  /// "Salvar só a foto" — only valid from an [OcrNoText] error; saves the
286	  /// fixed, non-empty placeholder content (the contract's
287	  /// `content.minLength: 1` forbids an empty save).
288	  Future<void> saveWithoutText() async {
289	    final current = state;
290	    if (current is! PhotoError || current.kind != PhotoErrorKind.ocrNoText) {
291	      return;
292	    }
293	    await _save(
294	      path: current.path,
295	      mimeType: current.mimeType,
296	      text: _noTextPlaceholder,
297	    );
298	  }
299	
300	  /// Mirrors the Texto/Áudio fields' own `updateText` — keeps the
301	  /// recognized text editable before Salvar, and keeps a save-failure
302	  /// retry's text editable too (same as `AudioEntryCubit.updateText`'s
303	  /// own `AudioError` branch).
304	  void updateText(String text) {
305	    final current = state;
306	    if (current is PhotoRecognized && !current.saving) {
307	      emit(current.copyWith(text: text));
308	    } else if (current is PhotoError &&
309	        current.kind == PhotoErrorKind.generic &&
310	        current.text != null) {
311	      emit(
312	        PhotoError(
313	          path: current.path,
314	          mimeType: current.mimeType,
315	          message: current.message,
316	          kind: current.kind,
317	          text: text,
318	        ),
319	      );
320	    }
321	  }
322	
323	  /// I/O matrix's "Happy path"/"Save fails" rows: fires `POST /entries`
324	  /// with `source: photo` for the current (possibly edited) recognized
325	  /// text. Also callable from a save-failure [PhotoError] (non-null
326	  /// [PhotoError.text]), mirroring `AudioEntryCubit.save()`'s own
327	  /// re-save-on-retry behavior.
328	  Future<void> save() async {
329	    final current = state;
330	    final String path;
331	    final String mimeType;
332	    final String text;
333	    if (current is PhotoRecognized && !current.saving) {
334	      path = current.path;
335	      mimeType = current.mimeType;
336	      text = current.text.trim();
337	    } else if (current is PhotoError &&
338	        current.kind == PhotoErrorKind.generic &&
339	        current.text != null) {
340	      path = current.path;
341	      mimeType = current.mimeType;
342	      text = current.text!.trim();
343	    } else {
344	      return;
345	    }
346	    if (text.isEmpty) {
347	      return;
348	    }
349	    await _save(path: path, mimeType: mimeType, text: text);
350	  }
351	
352	  Future<void> _save({
353	    required String path,
354	    required String mimeType,
355	    required String text,
356	  }) async {
357	    emit(
358	      PhotoRecognized(path: path, mimeType: mimeType, text: text, saving: true),
359	    );
360	    final result = await _entriesRepository.create(
361	      content: text,
362	      source: EntrySource.photo,
363	    );
364	    // Mirrors `AudioEntryCubit.save()`'s own `isClosed` guard — this
365	    // cubit's `close()` can race the awaited call above (e.g. the
366	    // modal's barrier is dismissed mid-save).
367	    if (isClosed) {
368	      return;
369	    }
370	    result.match(
371	      (failure) => emit(
372	        PhotoError(
373	          path: path,
374	          mimeType: mimeType,
375	          message: failure.message,
376	          kind: PhotoErrorKind.generic,
377	          text: text,
378	        ),
379	      ),
380	      (_) {
381	        // Review finding: the picked photo's temp file (written by
382	        // `image_picker` itself, not by this class, but still this
383	        // cubit's responsibility to clean up once it's done with it)
384	        // was never deleted after a successful save — fire-and-forget,
385	        // a deletion failure must never block the modal from closing.
386	        unawaited(_deletePickedFile(path));
387	        emit(const PhotoSaved());
388	      },
389	    );
390	  }
391	
392	  /// Called when the Foto tab loses focus mid-pick/mid-OCR
393	  /// (`InsertionModal`'s tab-switch listener) — I/O matrix's "Leave tab
394	  /// mid-pick/OCR" row: the in-flight picker/OCR call is discarded, no
395	  /// `create()` ever fires. A no-op for every other state when
396	  /// [discardPreserved] is `false` (the default) — in particular
397	  /// [PhotoRecognized]/[PhotoError], where the Never clause's trivial
398	  /// scope (resource safety only, not full Story 3.4 cancel-safety)
399	  /// means a tab switch must preserve the result rather than discard it
400	  /// — mirrors `AudioEntryCubit.cancel()`'s own `discardPreserved`
401	  /// convention exactly.
402	  ///
403	  /// [discardPreserved] — `InsertionModal.show()`'s `finally` also calls
404	  /// this (before `close()`) when the *whole modal* is dismissed (✕/
405	  /// swipe-down/barrier tap), not just the tab. In that case there's no
406	  /// "switch back to the tab later" to preserve for — the cubit is about
407	  /// to be closed — so a preserved [PhotoRecognized]/[PhotoError]'s
408	  /// picked-photo temp file would otherwise never be cleaned up and leak
409	  /// on disk forever (Review finding — the comment this replaced
410	  /// incorrectly claimed Foto "never creates a temp file of its own";
411	  /// `image_picker` does, every pick). Pass `true` only from that call
412	  /// site.
413	  Future<void> cancel({bool discardPreserved = false}) async {
414	    // Bumped unconditionally — including when the state below doesn't
415	    // match — so an in-flight `_pick`/`_recognize`/`retry` continuation
416	    // still sees the mismatch and aborts itself even while still awaiting
417	    // (Review-finding rationale mirrored from `AudioEntryCubit.cancel()`).
418	    _generation++;
419	    // Review finding: without this, leaving the Foto tab while the
420	    // native picker call itself (not yet `PhotoProcessing`) was still in
421	    // flight left `_picking` stuck `true` forever — the `_generation`
422	    // bump above already makes that stale continuation a no-op, so
423	    // resetting this eagerly is always safe.
424	    _picking = false;
425	    final current = state;
426	    if (current is PhotoProcessing) {
427	      unawaited(_deletePickedFile(current.path));
428	      emit(const PhotoIdle());
429	    } else if (discardPreserved) {
430	      final path = switch (current) {
431	        PhotoRecognized(path: final p) => p,
432	        PhotoError(path: final p) => p,
433	        _ => null,
434	      };
435	      if (path != null) {
436	        unawaited(_deletePickedFile(path));
437	      }
438	    }
439	  }
440	
441	  /// Best-effort cleanup for a picked-photo temp file this cubit is done
442	  /// with (saved successfully, abandoned for good by [cancel], or
443	  /// replaced by a fresh pick in [_pick]) — deletion failures are
444	  /// swallowed since nothing in the UI depends on this succeeding,
445	  /// mirroring `AudioEntryCubit._deleteRecordingFile()`.
446	  Future<void> _deletePickedFile(String path) async {
447	    try {
448	      await File(path).delete();
449	    } catch (_) {
450	      // Best-effort — a missing/already-deleted file, or a transient
451	      // disk error, is never worth surfacing to the user.
452	    }
453	  }
454	}
